     1→import { create } from "zustand";
     2→import { persist } from "zustand/middleware";
     3→import { createStackForLocation } from "@/navigation/location-navigation";
     4→import { createTabNavigationState, popTo as popNavigationState, pushPage as pushNavigationState } from "@/navigation/tab-navigation";
     5→import { locationToUrl, normalizeSettingsSection, urlToLocation } from "@/navigation/navigation-meta";
     6→import type {
     7→  BreadcrumbStackItem,
     8→  DesktopLocation,
     9→  PushPageOptions,
    10→  TabNavigationState,
    11→} from "@/navigation/navigation-meta";
    12→
    13→export type PageViewMode = "skill" | "page";
    14→
    15→export interface PageTab {
    16→  id: string;
    17→  pinned: boolean;
    18→  historyIndex: number;
    19→  navigationHistory: TabNavigationState[];
    20→  viewMode?: PageViewMode;
    21→}
    22→
    23→export interface ClosedTabSnapshot {
    24→  tab: PageTab;
    25→  closedAt: number;
    26→  originIndex: number;
    27→}
    28→
    29→interface TabState {
    30→  tabs: PageTab[];
    31→  activeTabId: string | null;
    32→  recentlyClosedTabs: ClosedTabSnapshot[];
    33→}
    34→
    35→interface OpenTabInput {
    36→  pinned?: boolean;
    37→  viewMode?: PageViewMode;
    38→  navigationState: TabNavigationState;
    39→}
    40→
    41→export interface TabViewModel extends PageTab {
    42→  currentState: TabNavigationState | null;
    43→  currentLocation: DesktopLocation | null;
    44→  label: string;
    45→  icon?: BreadcrumbStackItem["icon"];
    46→  descriptorId?: string;
    47→  meta?: BreadcrumbStackItem["meta"];
    48→  url: string | null;
    49→}
    50→
    51→interface TabActions {
    52→  openTab: (tab: OpenTabInput) => string;
    53→  closeTab: (tabId: string) => void;
    54→  closeOtherTabs: (tabId: string) => void;
    55→  closeTabsToRight: (tabId: string) => void;
    56→  setActiveTab: (tabId: string) => void;
    57→  pinTab: (tabId: string) => void;
    58→  unpinTab: (tabId: string) => void;
    59→  setViewMode: (tabId: string, mode: PageViewMode) => void;
    60→  moveTab: (fromIndex: number, toIndex: number) => void;
    61→  navigate: (tabId: string, url: string) => void;
    62→  navigateToLocation: (tabId: string, location: DesktopLocation, patch?: Partial<TabNavigationState>) => void;
    63→  replaceLocation: (tabId: string, next: TabNavigationState) => void;
    64→  pushLocation: (tabId: string, next: TabNavigationState) => void;
    65→  insertHistoryBeforeCurrent: (tabId: string, next: TabNavigationState) => void;
    66→  pushPage: (
    67→    tabId: string,
    68→    item: BreadcrumbStackItem,
    69→    location: DesktopLocation,
    70→    options?: PushPageOptions
    71→  ) => void;
    72→  popTo: (tabId: string, index: number) => void;
    73→  resetStack: (tabId: string, next: TabNavigationState) => void;
    74→  jumpToHistory: (tabId: string, historyIndex: number) => void;
    75→  goBack: (tabId: string) => void;
    76→  goForward: (tabId: string) => void;
    77→  canGoBack: (tabId: string) => boolean;
    78→  canGoForward: (tabId: string) => boolean;
    79→  getCurrentUrl: (tabId: string) => string | null;
    80→  getCurrentNavigationState: (tabId: string) => TabNavigationState | null;
    81→  closeAllTabs: () => void;
    82→  duplicateTab: (tabId: string) => string | null;
    83→  reopenClosedTab: () => string | null;
    84→  restoreTab: (tab: PageTab) => void;
    85→}
    86→
    87→const generateTabId = () =>
    88→  `tab-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
    89→const MAX_RECENTLY_CLOSED_TABS = 20;
    90→export const TAB_STORE_STORAGE_KEY = "viben-tab-store-v2";
    91→
    92→function findLastPinnedIndex(tabs: PageTab[]): number {
    93→  for (let index = tabs.length - 1; index >= 0; index -= 1) {
    94→    if (tabs[index].pinned) {
    95→      return index;
    96→    }
    97→  }
    98→  return -1;
    99→}
   100→
   101→function buildFallbackLocation(url: string): DesktopLocation {
   102→  if (url.startsWith("/workspace/") && url.includes("/apps")) {
   103→    const parts = url.split("/").filter(Boolean);
   104→    const workspaceId = parts[1];
   105→    if (workspaceId) {
   106→      return { kind: "workspace-apps", workspaceId };
   107→    }
   108→  }
   109→
   110→  if (url.startsWith("/documents")) {
   111→    return { kind: "documents" };
   112→  }
   113→
   114→  if (url.startsWith("/devices/pair")) {
   115→    return { kind: "device-pair" };
   116→  }
   117→
   118→  if (url.startsWith("/settings")) {
   119→    const section = url.split("/")[2];
   120→    return { kind: "settings", section: normalizeSettingsSection(section) };
   121→  }
   122→
   123→  return { kind: "documents" };
   124→}
   125→
   126→function buildStateFromUrl(url?: string): TabNavigationState {
   127→  const location = (url ? urlToLocation(url) : null) ?? buildFallbackLocation(url ?? "/documents");
   128→  return createTabNavigationState(location, createStackForLocation(location));
   129→}
   130→
   131→function isNavigationState(value: unknown): value is TabNavigationState {
   132→  if (!value || typeof value !== "object") return false;
   133→  const candidate = value as Partial<TabNavigationState>;
   134→  return Boolean(candidate.location && Array.isArray(candidate.breadcrumbStack));
   135→}
   136→
   137→function normalizeTab(tab: PageTab): PageTab {
   138→  const navigationHistory = tab.navigationHistory.filter(isNavigationState);
   139→  const safeHistory = navigationHistory.length > 0 ? navigationHistory : [buildStateFromUrl("/documents")];
   140→  const historyIndex = Math.min(
   141→    Math.max(tab.historyIndex ?? safeHistory.length - 1, 0),
   142→    safeHistory.length - 1
   143→  );
   144→
   145→  return {
   146→    id: tab.id,
   147→    pinned: Boolean(tab.pinned),
   148→    historyIndex,
   149→    navigationHistory: safeHistory,
   150→    viewMode: tab.viewMode,
   151→  };
   152→}
   153→
   154→function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
   155→  return {
   156→    tab: normalizeTab(snapshot.tab),
   157→    originIndex: snapshot.originIndex,
   158→    closedAt: snapshot.closedAt,
   159→  };
   160→}
   161→
   162→function cloneTabWithNewId(tab: PageTab, overrides?: Partial<PageTab>): PageTab {
   163→  return normalizeTab({
   164→    ...normalizeTab(tab),
   165→    ...overrides,
   166→    id: generateTabId(),
   167→  });
   168→}
   169→
   170→function createClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
   171→  return {
   172→    tab: normalizeTab(tab),
   173→    originIndex,
   174→    closedAt: Date.now(),
   175→  };
   176→}
   177→
   178→function pushClosedSnapshots(
   179→  stack: ClosedTabSnapshot[],
   180→  snapshots: ClosedTabSnapshot[]
   181→): ClosedTabSnapshot[] {
   182→  if (snapshots.length === 0) {
   183→    return stack;
   184→  }
   185→
   186→  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
   187→}
   188→
   189→function restoreClosedTabIntoTabs(
   190→  tabs: PageTab[],
   191→  snapshot: ClosedTabSnapshot
   192→): { tabs: PageTab[]; restoredTab: PageTab } {
   193→  const restoredTab = cloneTabWithNewId(snapshot.tab);
   194→  const nextTabs = [...tabs];
   195→  const insertIndex = Math.max(0, Math.min(snapshot.originIndex, nextTabs.length));
   196→  nextTabs.splice(insertIndex, 0, restoredTab);
   197→  return { tabs: nextTabs, restoredTab };
   198→}
   199→
   200→export function getTabCurrentState(tab: PageTab): TabNavigationState | null {
   201→  return tab.navigationHistory[tab.historyIndex] ?? null;
   202→}
   203→
   204→export function getTabCurrentLeaf(tab: PageTab): BreadcrumbStackItem | null {
   205→  const current = getTabCurrentState(tab);
   206→  return current?.breadcrumbStack[current.breadcrumbStack.length - 1] ?? null;
   207→}
   208→
   209→export function getTabUrl(tab: PageTab): string | null {
   210→  const current = getTabCurrentState(tab);
   211→  return current ? locationToUrl(current.location) : null;
   212→}
   213→
   214→export function getTabViewModel(tab: PageTab): TabViewModel {
   215→  const currentState = getTabCurrentState(tab);
   216→  const leaf = getTabCurrentLeaf(tab);
   217→  const url = getTabUrl(tab);
   218→
   219→  return {
   220→    ...tab,
   221→    currentState,
   222→    currentLocation: currentState?.location ?? null,
   223→    label: leaf?.label ?? currentState?.location.kind ?? "Untitled",
   224→    icon: leaf?.icon,
   225→    descriptorId: leaf?.descriptorId,
   226→    meta: leaf?.meta,
   227→    url,
   228→  };
   229→}
   230→
   231→function findHistoryEntryByLocation(
   232→  navigationHistory: TabNavigationState[],
   233→  historyIndex: number,
   234→  location: DesktopLocation
   235→): number {
   236→  const targetUrl = locationToUrl(location);
   237→  for (let index = historyIndex - 1; index >= 0; index -= 1) {
   238→    if (locationToUrl(navigationHistory[index].location) === targetUrl) {
   239→      return index;
   240→    }
   241→  }
   242→  return -1;
   243→}
   244→
   245→export const useTabStore = create<TabState & TabActions>()(
   246→  persist(
   247→    (set, get) => ({
   248→      tabs: [],
   249→      activeTabId: null,
   250→      recentlyClosedTabs: [],
   251→
   252→      openTab: (tabData) => {
   253→        const id = generateTabId();
   254→        const newTab = normalizeTab({
   255→          id,
   256→          pinned: tabData.pinned ?? false,
   257→          navigationHistory: [tabData.navigationState],
   258→          historyIndex: 0,
   259→          viewMode: tabData.viewMode,
   260→        });
   261→
   262→        set((state) => ({
   263→          tabs: [...state.tabs, newTab],
   264→          activeTabId: id,
   265→        }));
   266→
   267→        return id;
   268→      },
   269→
   270→      closeTab: (tabId) => {
   271→        set((state) => {
   272→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   273→          if (tabIndex === -1) return state;
   274→
   275→          const recentlyClosedTabs = pushClosedSnapshots(
   276→            state.recentlyClosedTabs,
   277→            [createClosedSnapshot(state.tabs[tabIndex], tabIndex)]
   278→          );
   279→          const tabs = state.tabs.filter((tab) => tab.id !== tabId);
   280→          let activeTabId = state.activeTabId;
   281→
   282→          if (state.activeTabId === tabId) {
   283→            if (tabs.length === 0) {
   284→              activeTabId = null;
   285→            } else if (tabIndex >= tabs.length) {
   286→              activeTabId = tabs[tabs.length - 1].id;
   287→            } else {
   288→              activeTabId = tabs[tabIndex].id;
   289→            }
   290→          }
   291→
   292→          return { tabs, activeTabId, recentlyClosedTabs };
   293→        });
   294→      },
   295→
   296→      closeOtherTabs: (tabId) => {
   297→        set((state) => {
   298→          const snapshots = state.tabs
   299→            .map((tab, index) => ({ tab, index }))
   300→            .filter(({ tab }) => !tab.pinned && tab.id !== tabId)
   301→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   302→
   303→          return {
   304→            tabs: state.tabs.filter((tab) => tab.pinned || tab.id === tabId),
   305→            activeTabId: tabId,
   306→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   307→          };
   308→        });
   309→      },
   310→
   311→      closeTabsToRight: (tabId) => {
   312→        set((state) => {
   313→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   314→          if (tabIndex === -1) return state;
   315→
   316→          const snapshots = state.tabs
   317→            .map((tab, index) => ({ tab, index }))
   318→            .filter(({ tab, index }) => index > tabIndex && !tab.pinned)
   319→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   320→          const closingIds = new Set(snapshots.map((snapshot) => snapshot.tab.id));
   321→          const tabs = state.tabs.filter((tab) => !closingIds.has(tab.id));
   322→          const activeTabId = tabs.some((tab) => tab.id === state.activeTabId)
   323→            ? state.activeTabId
   324→            : tabId;
   325→
   326→          return {
   327→            tabs,
   328→            activeTabId,
   329→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   330→          };
   331→        });
   332→      },
   333→
   334→      setActiveTab: (tabId) => {
   335→        set({ activeTabId: tabId });
   336→      },
   337→
   338→      pinTab: (tabId) => {
   339→        set((state) => {
   340→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   341→          if (tabIndex === -1) return state;
   342→
   343→          const tab = state.tabs[tabIndex];
   344→          if (tab.pinned) return state;
   345→
   346→          const tabs = [...state.tabs];
   347→          tabs.splice(tabIndex, 1);
   348→
   349→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   350→          tabs.splice(insertIndex, 0, { ...tab, pinned: true });
   351→
   352→          return { tabs };
   353→        });
   354→      },
   355→
   356→      unpinTab: (tabId) => {
   357→        set((state) => {
   358→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   359→          if (tabIndex === -1) return state;
   360→
   361→          const tab = state.tabs[tabIndex];
   362→          if (!tab.pinned) return state;
   363→
   364→          const tabs = [...state.tabs];
   365→          tabs.splice(tabIndex, 1);
   366→
   367→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   368→          tabs.splice(insertIndex, 0, { ...tab, pinned: false });
   369→
   370→          return { tabs };
   371→        });
   372→      },
   373→
   374→      setViewMode: (tabId, mode) => {
   375→        set((state) => ({
   376→          tabs: state.tabs.map((tab) =>
   377→            tab.id === tabId ? { ...tab, viewMode: mode } : tab
   378→          ),
   379→        }));
   380→      },
   381→
   382→      moveTab: (fromIndex, toIndex) => {
   383→        set((state) => {
   384→          if (
   385→            fromIndex === toIndex ||
   386→            fromIndex < 0 ||
   387→            toIndex < 0 ||
   388→            fromIndex >= state.tabs.length ||
   389→            toIndex >= state.tabs.length
   390→          ) {
   391→            return state;
   392→          }
   393→
   394→          const tabs = [...state.tabs];
   395→          const [moved] = tabs.splice(fromIndex, 1);
   396→          tabs.splice(toIndex, 0, moved);
   397→          return { tabs };
   398→        });
   399→      },
   400→
   401→      navigate: (tabId, url) => {
   402→        get().pushLocation(tabId, buildStateFromUrl(url));
   403→      },
   404→
   405→      navigateToLocation: (tabId, location, patch) => {
   406→        get().pushLocation(
   407→          tabId,
   408→          createTabNavigationState(
   409→            location,
   410→            patch?.breadcrumbStack ?? createStackForLocation(location),
   411→            patch
   412→          )
   413→        );
   414→      },
   415→
   416→      replaceLocation: (tabId, next) => {
   417→        set((state) => ({
   418→          tabs: state.tabs.map((tab) => {
   419→            if (tab.id !== tabId) return tab;
   420→            const current = normalizeTab(tab);
   421→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
   422→            return normalizeTab({
   423→              ...current,
   424→              navigationHistory: [...baseHistory, next],
   425→              historyIndex: baseHistory.length,
   426→            });
   427→          }),
   428→        }));
   429→      },
   430→
   431→      pushLocation: (tabId, next) => {
   432→        set((state) => ({
   433→          tabs: state.tabs.map((tab) => {
   434→            if (tab.id !== tabId) return tab;
   435→            const current = normalizeTab(tab);
   436→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex + 1);
   437→            return normalizeTab({
   438→              ...current,
   439→              navigationHistory: [...baseHistory, next],
   440→              historyIndex: baseHistory.length,
   441→            });
   442→          }),
   443→        }));
   444→      },
   445→
   446→      insertHistoryBeforeCurrent: (tabId, next) => {
   447→        set((state) => ({
   448→          tabs: state.tabs.map((tab) => {
   449→            if (tab.id !== tabId) return tab;
   450→            const current = normalizeTab(tab);
   451→            const before = current.navigationHistory.slice(0, current.historyIndex);
   452→            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
   453→            return normalizeTab({
   454→              ...current,
   455→              navigationHistory: [...before, next, ...fromCurrent],
   456→              historyIndex: before.length,
   457→            });
   458→          }),
   459→        }));
   460→      },
   461→
   462→      pushPage: (tabId, item, location, options) => {
   463→        const tab = get().tabs.find((entry) => entry.id === tabId);
   464→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   465→        if (!current) return;
   466→        get().pushLocation(tabId, pushNavigationState(current, item, location, options));
   467→      },
   468→
   469→      popTo: (tabId, index) => {
   470→        const tab = get().tabs.find((entry) => entry.id === tabId);
   471→        const current = tab ? normalizeTab(tab) : null;
   472→        const currentState = current ? getTabCurrentState(current) : null;
   473→        if (!current || !currentState) return;
   474→
   475→        const nextState = popNavigationState(currentState, index);
   476→        const matchIndex = findHistoryEntryByLocation(
   477→          current.navigationHistory,
   478→          current.historyIndex,
   479→          nextState.location
   480→        );
   481→
   482→        if (matchIndex >= 0) {
   483→          get().jumpToHistory(tabId, matchIndex);
   484→          return;
   485→        }
   486→
   487→        get().insertHistoryBeforeCurrent(tabId, nextState);
   488→      },
   489→
   490→      resetStack: (tabId, next) => {
   491→        get().replaceLocation(tabId, next);
   492→      },
   493→
   494→      jumpToHistory: (tabId, historyIndex) => {
   495→        set((state) => ({
   496→          tabs: state.tabs.map((tab) => {
   497→            if (tab.id !== tabId) return tab;
   498→            const current = normalizeTab(tab);
   499→            return normalizeTab({
   500→              ...current,
   501→              historyIndex,
   502→            });
   503→          }),
   504→        }));
   505→      },
   506→
   507→      goBack: (tabId) => {
   508→        set((state) => ({
   509→          tabs: state.tabs.map((tab) => {
   510→            if (tab.id !== tabId) return tab;
   511→            const current = normalizeTab(tab);
   512→            if (current.historyIndex <= 0) return current;
   513→            return {
   514→              ...current,
   515→              historyIndex: current.historyIndex - 1,
   516→            };
   517→          }),
   518→        }));
   519→      },
   520→
   521→      goForward: (tabId) => {
   522→        set((state) => ({
   523→          tabs: state.tabs.map((tab) => {
   524→            if (tab.id !== tabId) return tab;
   525→            const current = normalizeTab(tab);
   526→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   527→              return current;
   528→            }
   529→            return {
   530→              ...current,
   531→              historyIndex: current.historyIndex + 1,
   532→            };
   533→          }),
   534→        }));
   535→      },
   536→
   537→      canGoBack: (tabId) => {
   538→        const tab = get().tabs.find((item) => item.id === tabId);
   539→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   540→      },
   541→
   542→      canGoForward: (tabId) => {
   543→        const tab = get().tabs.find((item) => item.id === tabId);
   544→        if (!tab) return false;
   545→        const current = normalizeTab(tab);
   546→        return current.historyIndex < current.navigationHistory.length - 1;
   547→      },
   548→
   549→      getCurrentUrl: (tabId) => {
   550→        const tab = get().tabs.find((item) => item.id === tabId);
   551→        return tab ? getTabUrl(normalizeTab(tab)) : null;
   552→      },
   553→
   554→      getCurrentNavigationState: (tabId) => {
   555→        const tab = get().tabs.find((item) => item.id === tabId);
   556→        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
   557→      },
   558→
   559→      closeAllTabs: () => {
   560→        set((state) => {
   561→          const snapshots = state.tabs
   562→            .map((tab, index) => ({ tab, index }))
   563→            .filter(({ tab }) => !tab.pinned)
   564→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   565→          const tabs = state.tabs.filter((tab) => tab.pinned);
   566→          return {
   567→            tabs,
   568→            activeTabId: tabs[0]?.id ?? null,
   569→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   570→          };
   571→        });
   572→      },
   573→
   574→      duplicateTab: (tabId) => {
   575→        const state = get();
   576→        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   577→        if (tabIndex === -1) return null;
   578→
   579→        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
   580→          pinned: false,
   581→        });
   582→
   583→        set((current) => {
   584→          const tabs = [...current.tabs];
   585→          tabs.splice(tabIndex + 1, 0, duplicatedTab);
   586→          return {
   587→            tabs,
   588→            activeTabId: duplicatedTab.id,
   589→          };
   590→        });
   591→
   592→        return duplicatedTab.id;
   593→      },
   594→
   595→      reopenClosedTab: () => {
   596→        let restoredTabId: string | null = null;
   597→
   598→        set((current) => {
   599→          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
   600→          if (!nextSnapshot) return current;
   601→
   602→          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
   603→          restoredTabId = restored.restoredTab.id;
   604→
   605→          return {
   606→            tabs: restored.tabs,
   607→            activeTabId: restored.restoredTab.id,
   608→            recentlyClosedTabs: restSnapshots,
   609→          };
   610→        });
   611→
   612→        return restoredTabId;
   613→      },
   614→
   615→      restoreTab: (tab) => {
   616→        const restoredTab = cloneTabWithNewId(tab);
   617→        set((state) => ({
   618→          tabs: [...state.tabs, restoredTab],
   619→          activeTabId: restoredTab.id,
   620→        }));
   621→      },
   622→    }),
   623→    {
   624→      name: TAB_STORE_STORAGE_KEY,
   625→      partialize: (state) => ({
   626→        tabs: state.tabs,
   627→        activeTabId: state.activeTabId,
   628→        recentlyClosedTabs: state.recentlyClosedTabs,
   629→      }),
   630→      merge: (persisted, current) => {
