   634→        const activeTabId =
   635→          persistedState?.activeTabId && tabIds.has(persistedState.activeTabId)
   636→            ? persistedState.activeTabId
   637→            : tabs[0]?.id ?? null;
   638→
   639→        return {
   640→          ...current,
   641→          tabs,
   642→          activeTabId,
   643→          recentlyClosedTabs: (persistedState?.recentlyClosedTabs ?? [])
   644→            .filter(Boolean)
   645→            .map(normalizeSnapshot),
   646→        };
   647→      },
   648→    }
   649→  )
   650→);
   651→
   652→export const selectActiveTab = (state: TabState) =>
   653→  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
