    12→export function TabRouterBridge() {
    13→  const queryClient = useQueryClient();
    14→  const navigate = useNavigate();
    15→  const location = useLocation();
    16→  const { getWorkspace } = useLocalWorkspaces();
    17→
    18→  const activeTabId = useTabStore((state) => state.activeTabId);
    19→  const activeTab = useTabStore(selectActiveTab);
    20→  const openTab = useTabStore((state) => state.openTab);
    21→  const navigateToLocation = useTabStore((state) => state.navigateToLocation);
    22→  const setActiveWorkspace = useWorkspaceStore((s) => s.setActiveWorkspace);
    23→  const activeWorkspaceId = useWorkspaceStore((s) => s.activeWorkspaceId);
    24→
    25→  const currentUrl = useMemo(
    26→    () =>
    27→      `${location.pathname}${location.search}${location.hash}`,
    28→    [location.hash, location.pathname, location.search]
    29→  );
    30→
    31→  const syncLockRef = useRef<string | null>(null);
    32→  const targetUrl = useMemo(() => {
    33→    if (!activeTab) return null;
    34→    const currentState = activeTab.navigationHistory[activeTab.historyIndex];
    35→    return currentState ? locationToUrl(currentState.location) : null;
    36→  }, [activeTab]);
    37→  const activeTabState = useMemo(
    38→    () =>
    39→      activeTab?.navigationHistory[activeTab.historyIndex] ?? null,
    40→    [activeTab]
    41→  );
    42→
    43→  // Sync active tab's workspaceId to workspace store so that ChatPopup
    44→  // and other global components always reflect the current tab's workspace.
    45→  useEffect(() => {
    46→    if (!activeTabState) return;
    47→    const loc = activeTabState.location;
    48→    const tabWorkspaceId = "workspaceId" in loc ? loc.workspaceId : null;
    49→    if (tabWorkspaceId && tabWorkspaceId !== activeWorkspaceId) {
    50→      setActiveWorkspace(tabWorkspaceId);
    51→    }
    52→  }, [activeTabState, activeWorkspaceId, setActiveWorkspace]);
    53→
    54→  const resolveNavigation = useMemo(
    55→    () =>
    56→      (nextLocation: DesktopLocation, input?: { title?: string }) => {
    57→        const workspaceId =
    58→          "workspaceId" in nextLocation ? nextLocation.workspaceId : undefined;
    59→        const workspace = workspaceId ? getWorkspace(workspaceId) : undefined;
    60→        const cachedPages = workspace?.path
    61→          ? queryClient.getQueryData<ListPagesResult | PageConfig[]>(
    62→              pageKeys.list(workspace.path)
    63→            )
    64→          : undefined;
    65→        const pages = Array.isArray(cachedPages)
    66→          ? cachedPages
    67→          : cachedPages?.pages;
    68→
    69→        return resolveLocationNavigation({
    70→          location: nextLocation,
    71→          workspace,
    72→          pages,
    73→          title: input?.title,
    74→        });
    75→      },
    76→    [getWorkspace, queryClient]
    77→  );
    78→
    79→  useEffect(() => {
    80→    if (!activeTabId || !targetUrl) return;
    81→    if (!targetUrl || targetUrl === currentUrl) return;
    82→    if (syncLockRef.current === `router:${targetUrl}`) {
    83→      syncLockRef.current = null;
    84→      return;
    85→    }
    86→
    87→    syncLockRef.current = `tab:${targetUrl}`;
    88→    navigate(targetUrl, { replace: true });
    89→  }, [activeTabId, currentUrl, navigate, targetUrl]);
    90→
    91→  useEffect(() => {
    92→    if (syncLockRef.current === `tab:${currentUrl}`) {
    93→      syncLockRef.current = null;
    94→      return;
    95→    }
    96→
    97→    const parsed = urlToLocation(currentUrl);
    98→    if (!parsed) return;
    99→
   100→    if (!activeTabId) {
   101→      const resolved = resolveNavigation(parsed);
   102→      openTab({
   103→        pinned: false,
   104→        navigationState: {
   105→          location: parsed,
   106→          breadcrumbStack: resolved.breadcrumbStack,
   107→        },
   108→      });
   109→      return;
   110→    }
   111→
   112→    const currentStateUrl = activeTabState
   113→      ? locationToUrl(activeTabState.location)
   114→      : null;
   115→    if (currentStateUrl === currentUrl) return;
   116→
   117→    const resolved = resolveNavigation(parsed);
   118→    syncLockRef.current = `router:${currentUrl}`;
   119→    navigateToLocation(activeTabId, parsed, {
   120→      breadcrumbStack: resolved.breadcrumbStack,
   121→    });
   122→  }, [
   123→    activeTabId,
   124→    activeTabState,
   125→    currentUrl,
   126→    navigateToLocation,
   127→    openTab,
   128→    resolveNavigation,
   129→  ]);
   130→
   131→  return null;
   132→}
