   450→}
   451→
   452→function safeHostname(url: string): string {
   453→  try {
   454→    return new URL(url).hostname;
   455→  } catch {
   456→    return url;
   457→  }
   458→}
   459→
   460→function buildLocationFromLegacyUrl(url: string): DesktopLocation {
   461→  const parsed = urlToLocation(url);
   462→  if (parsed) {
   463→    return parsed;
   464→  }
   465→
   466→  if (url === "/documents") {
   467→    return { kind: "documents" };
   468→  }
   469→  if (url === "/devices/pair") {
   470→    return { kind: "device-pair" };
   471→  }
   472→  if (url.startsWith("/settings")) {
   473→    const section = url.split("/")[2];
   474→    return { kind: "settings", section: normalizeSettingsSection(section) };
   475→  }
   476→
   477→  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
   478→    return { kind: "global-route", path: url };
   479→  }
   480→
   481→  if (url.startsWith("/workspace/page")) {
   482→    const parsed = new URL(url, "http://desktop.local");
   483→    const workspaceId = parsed.searchParams.get("workspace_id");
   484→    const pagePath = parsed.searchParams.get("page_path");
   485→    return {
   486→      kind: "workspace-page",
   487→      workspaceId: workspaceId ?? "global",
   488→      pageSlug:
   489→        pagePath?.replace(/^pages\//, "").replace(/\/SKILL\.md$/, "") ?? "page",
   490→    };
   491→  }
   492→
   493→  if (url.startsWith("/workspace/")) {
   494→    const parsed = new URL(url, "http://desktop.local");
   495→    const parts = parsed.pathname.split("/").filter(Boolean);
   496→    const workspaceId = parts[1];
   497→    if (!workspaceId) {
   498→      return { kind: "documents" };
   499→    }
   500→
   501→    if (parts.length === 2) {
   502→      return { kind: "workspace-home", workspaceId };
   503→    }
   504→
   505→    if (parts[2] === "apps" && !parts[3]) {
   506→      return { kind: "workspace-apps", workspaceId };
   507→    }
   508→
   509→    if (parts[2] === "page" && parts[3]) {
   510→      return {
   511→        kind: "workspace-page",
   512→        workspaceId,
   513→        pageSlug: parts
   514→          .slice(3)
   515→          .map((part) => decodeURIComponent(part))
   516→          .join("/"),
   517→      };
   518→    }
   519→
   520→    if (parts[2] === "agent" && parts[3]) {
   521→      return {
   522→        kind: "workspace-agent-detail",
   523→        workspaceId,
   524→        agentId: decodeURIComponent(parts[3]),
   525→      };
   526→    }
   527→
   528→    if (parts[2] === "executor" && parts[3]) {
   529→      return {
   530→        kind: "workspace-executor-detail",
   531→        workspaceId,
   532→        executorType: decodeURIComponent(parts[3]),
   533→      };
   534→    }
   535→
   536→    if (parts[2] === "web") {
   537→      return {
   538→        kind: "workspace-web",
   539→        workspaceId,
   540→        url: parsed.searchParams.get("url") ?? "",
   541→        title: parsed.searchParams.get("title") ?? "Web",
   542→        sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined,
   543→        webId: parsed.searchParams.get("web_id") ?? undefined,
   544→      };
   545→    }
   546→
   547→    return {
   548→      kind: "workspace-section",
   549→      workspaceId,
   550→      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
   551→    };
   552→  }
   553→
   554→  return { kind: "global-route", path: url };
   555→}
   556→

