    34→export function SidebarIconButton({
    35→  icon,
    36→  tooltip,
    37→  href,
    38→  onClick,
    39→  disabled,
    40→}: SidebarIconButtonProps) {
    41→  const { openPath } = useDesktopRouting();
    42→  const location = useLocation();
