    75→              "hover:bg-sidebar-accent",
    76→              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
    77→              isActive && "bg-sidebar-accent text-sidebar-accent-foreground",
    78→              disabled && "opacity-50 cursor-not-allowed"
    79→            )}
    80→          >
