   715→
   716→function WorkspaceNavItemComponent({ item, workspaceId, collapsed, onNavigate }: WorkspaceNavItemComponentProps) {
   717→  const { t } = useTranslation();
   718→  const location = useLocation();
   719→  const title = t(item.titleKey);
   720→  const href = `/workspace/${workspaceId}/${item.path}`;
   721→  const agentCompatHref = `/workspace/${workspaceId}/agent`;
   722→
   723→  // Check if this item is active
   724→  const isActive =
   725→    location.pathname === href ||
   726→    location.pathname.startsWith(href + "/") ||
   727→    (item.path === "agents" &&
   728→      (location.pathname === agentCompatHref ||
   729→        location.pathname.startsWith(agentCompatHref + "/")));
   730→
   731→  // Use item path as icon name
   732→  const iconName = item.path;
   733→
   734→  const handleClick = () => {
   735→    if (onNavigate) {
   736→      onNavigate(workspaceId, item.path, title, { type: "lucide", value: iconName });
   737→    }
   738→  };
   739→
   740→  // Collapsed view - use unified SidebarIconButton component with centering wrapper
   741→  if (collapsed) {
   742→    return (
   743→      <div className="grid place-items-center w-full">
   744→        <SidebarIconButton
   745→          icon={<item.icon className="h-4 w-4" />}
   746→          tooltip={title}
   747→          onClick={handleClick}
   748→        />
   749→      </div>
   750→    );
   751→  }
   752→
   753→  // Expanded view - full button with text
   754→  return (
   755→    <button
   756→      type="button"
   757→      onClick={handleClick}
   758→      className={cn(
   759→        "group relative flex items-center gap-3 px-2 py-2 rounded-lg text-sm w-full text-left",
